examples.template:
MonarchDocumentRelations(
    relations,
    candidates: library,
    onOpen: { _ in },
    onAdd: { targetID, type in
        if let target = library.first(where: { $0.id == targetID }) {
            relations.append(MonarchDocumentRelation(id: "r\(relations.count + 1)", type: type, target: target))
        }
    },
    onRemove: { relationID in relations.removeAll { $0.id == relationID } }
)

